/**
 * Checkout-wizard state machine (vanilla TypeScript, no framework).
 *
 * States: cart -> shipping -> payment -> review -> confirmed
 *
 * Design decisions (documented per spec):
 *
 * - ILLEGAL TRANSITIONS: an event that is not legal in the current state
 *   throws an Error. We chose throw-over-no-op so misuse fails loudly at
 *   the call site instead of silently swallowing events.
 * - GUARD FAILURE: NEXT out of `shipping` invokes the caller-supplied
 *   validate() callback; if it returns a non-empty error array the machine
 *   STAYS in `shipping` (a no-op, not a throw) and the errors are exposed
 *   via getErrors(). This is not "illegal" — it is a guarded rejection.
 * - TERMINAL: `confirmed` accepts no further events; any event thrown at it
 *   throws (consistent with the illegal-transition policy above).
 */

export type WizardState = 'cart' | 'shipping' | 'payment' | 'review' | 'confirmed';

export type WizardEvent = 'NEXT' | 'BACK' | 'EDIT_SHIPPING' | 'SUBMIT';

/** Returns validation errors; empty array means valid. */
export type ShippingValidator = () => string[];

export interface Wizard {
  /** Current state name. */
  getState(): WizardState;
  /** Errors from the last failed guard check on `shipping` (empty if none). */
  getErrors(): string[];
  /** Fire an event at the machine. Throws on illegal transitions. */
  dispatch(event: WizardEvent): void;
}

const ORDER: readonly WizardState[] = ['cart', 'shipping', 'payment', 'review', 'confirmed'] as const;

export function createWizard(validate?: ShippingValidator): Wizard {
  let state: WizardState = 'cart';
  let errors: string[] = [];

  return {
    getState: () => state,

    getErrors: () => errors.slice(),

    dispatch(event: WizardEvent): void {
      switch (state) {
        case 'cart':
          if (event === 'NEXT') {
            state = 'shipping';
            return;
          }
          break;

        case 'shipping':
          if (event === 'NEXT') {
            // Guarded transition: consult the validate callback.
            const result = validate ? validate() : [];
            if (result.length > 0) {
              errors = result.slice();
              return; // stay put; errors exposed via getErrors()
            }
            errors = [];
            state = 'payment';
            return;
          }
          if (event === 'BACK') {
            state = 'cart';
            return;
          }
          break;

        case 'payment':
          if (event === 'NEXT') {
            state = 'review';
            return;
          }
          if (event === 'BACK') {
            state = 'shipping';
            return;
          }
          break;

        case 'review':
          if (event === 'SUBMIT') {
            state = 'confirmed';
            return;
          }
          if (event === 'BACK') {
            state = 'payment';
            return;
          }
          if (event === 'EDIT_SHIPPING') {
            state = 'shipping';
            return;
          }
          break;

        case 'confirmed':
          // Terminal state: no events are accepted.
          break;
      }

      throw new Error(`Illegal transition: ${event} in state ${state}`);
    },
  };
}

