import { describe, it, expect } from 'vitest';
import { createWizard, type Wizard, type WizardState } from '../src/machine.js';

/** Drive the machine along cart -> shipping -> payment -> review. */
function toReview(validate: () => string[] = []): Wizard {
  const w = createWizard(validate);
  w.dispatch('NEXT'); // cart -> shipping
  w.dispatch('NEXT'); // shipping -> payment (guard passes)
  w.dispatch('NEXT'); // payment -> review
  return w;
}

describe('initial state', () => {
  it('starts in cart', () => {
    expect(createWizard().getState()).toBe<WizardState>('cart');
  });

  it('exposes no errors initially', () => {
    expect(createWizard().getErrors()).toEqual([]);
  });
});

describe('legal transitions', () => {
  it('cart --NEXT--> shipping', () => {
    const w = createWizard();
    w.dispatch('NEXT');
    expect(w.getState()).toBe('shipping');
  });

  it('shipping --BACK--> cart', () => {
    const w = createWizard();
    w.dispatch('NEXT');
    w.dispatch('BACK');
    expect(w.getState()).toBe('cart');
  });

  it('shipping --NEXT--> payment when guard passes', () => {
    const w = createWizard(() => []);
    w.dispatch('NEXT');
    w.dispatch('NEXT');
    expect(w.getState()).toBe('payment');
  });

  it('shipping --NEXT--> payment with no validate callback supplied', () => {
    const w = createWizard(); // no guard at all: unguarded NEXT is legal
    w.dispatch('NEXT');
    w.dispatch('NEXT');
    expect(w.getState()).toBe('payment');
  });

  it('shipping --NEXT--> payment clears previous errors', () => {
    const w = createWizard(() => ['bad']);
    w.dispatch('NEXT');
    w.dispatch('NEXT'); // guard fails, errors set
    expect(w.getErrors()).toEqual(['bad']);
    const w2 = createWizard(() => []);
    w2.dispatch('NEXT');
    w2.dispatch('NEXT'); // now passes; errors must be cleared
    expect(w2.getErrors()).toEqual([]);
  });

  it('payment --BACK--> shipping', () => {
    const w = createWizard();
    w.dispatch('NEXT');
    w.dispatch('NEXT');
    w.dispatch('BACK');
    expect(w.getState()).toBe('shipping');
  });

  it('payment --NEXT--> review', () => {
    const w = createWizard();
    w.dispatch('NEXT');
    w.dispatch('NEXT');
    w.dispatch('NEXT');
    expect(w.getState()).toBe('review');
  });

  it('review --EDIT_SHIPPING--> shipping', () => {
    const w = toReview();
    w.dispatch('EDIT_SHIPPING');
    expect(w.getState()).toBe('shipping');
  });

  it('review --BACK--> payment', () => {
    const w = toReview();
    w.dispatch('BACK');
    expect(w.getState()).toBe('payment');
  });

  it('review --SUBMIT--> confirmed', () => {
    const w = toReview();
    w.dispatch('SUBMIT');
    expect(w.getState()).toBe('confirmed');
  });

  it('full happy path round trip including EDIT_SHIPPING re-entry', () => {
    let valid = false;
    const w = createWizard(() => (valid ? [] : ['missing zip']));
    w.dispatch('NEXT');           // cart -> shipping
    expect(() => w.dispatch('NEXT')).toThrow(); // guarded out
    valid = true;
    w.dispatch('NEXT');           // shipping -> payment
    w.dispatch('NEXT');           // payment -> review
    w.dispatch('EDIT_SHIPPING');  // review -> shipping
    w.dispatch('NEXT');           // shipping -> payment (guard now passes)
    w.dispatch('NEXT');           // payment -> review
    w.dispatch('SUBMIT');         // review -> confirmed
    expect(w.getState()).toBe('confirmed');
  });
});

describe('illegal transitions (policy: throw)', () => {
  /**
   * POLICY: an event that is not legal in the current state THROWS.
   * We deliberately chose throw over silent no-op so misuse fails loudly.
   */
  const illegal: Array<[WizardState, Parameters<Wizard['dispatch']>[0]]> = [
    ['cart', 'BACK'],
    ['cart', 'SUBMIT'],
    ['cart', 'EDIT_SHIPPING'],
    ['shipping', 'SUBMIT'],
    ['shipping', 'EDIT_SHIPPING'],
    ['payment', 'BACK'], // placeholder replaced below; see explicit list per state
  ];

  it.each(illegal.filter(([, e]) => !(e === 'BACK')))('%s rejects %s', (state, event) => {
    // Build a machine parked in `state` via legal moves only.
    const w = createWizard(() => []);
    if (state !== 'cart') {
      w.dispatch('NEXT'); // -> shipping
      if (state !== 'shipping') {
        w.dispatch('NEXT'); // -> payment
        if (state === 'review') w.dispatch('NEXT'); // -> review
      }
    }
    expect(() => w.dispatch(event)).toThrow(/Illegal transition/);
    // And it must not have moved.
    expect(w.getState()).toBe(state);
  });

  it('cart rejects BACK explicitly', () => {
    const w = createWizard();
    expect(() => w.dispatch('BACK')).toThrow(/Illegal transition/);
    expect(w.getState()).toBe('cart');
  });

  it('payment rejects SUBMIT and EDIT_SHIPPING', () => {
    const w = createWizard();
    w.dispatch('NEXT');
    w.dispatch('NEXT'); // -> payment
    expect(() => w.dispatch('SUBMIT')).toThrow(/Illegal transition/);
    expect(() => w.dispatch('EDIT_SHIPPING')).toThrow(/Illegal transition/);
    expect(w.getState()).toBe('payment');
  });

  it('review rejects NEXT', () => {
    const w = toReview();
    expect(() => w.dispatch('NEXT')).toThrow(/Illegal transition/);
    expect(w.getState()).toBe('review');
  });
});

describe('guard failure path (guarded rejection: stay put + getErrors)', () => {
  it('stays in shipping and exposes errors from validate()', () => {
    const errors = ['card number required', 'expiry in the past'];
    const w = createWizard(() => errors);
    w.dispatch('NEXT'); // cart -> shipping
    w.dispatch('NEXT'); // guard fails
    expect(w.getState()).toBe('shipping');
    expect(w.getErrors()).toEqual(errors);
  });

  it('does not mutate the caller-supplied array', () => {
    const errors = ['oops'];
    const w = createWizard(() => errors);
    w.dispatch('NEXT');
    w.dispatch('NEXT');
    w.dispatch('NEXT'); // fail again
    expect(errors).toEqual(['oops']);
    expect(w.getErrors()).not.toBe(errors); // defensive copy
  });

  it('allows retry after fixing validation', () => {
    let result: string[] = ['fix me'];
    const w = createWizard(() => result);
    w.dispatch('NEXT');
    w.dispatch('NEXT');
    expect(w.getState()).toBe('shipping');
    result = [];
    w.dispatch('NEXT');
    expect(w.getState()).toBe('payment');
    expect(w.getErrors()).toEqual([]);
  });

  it('re-entering shipping via EDIT_SHIPPING then failing guard keeps working', () => {
    const w = createWizard(() => ['nope']);
    w.dispatch('NEXT');
    w.dispatch('NEXT'); // fail -> still shipping
    w.dispatch('NEXT'); // fail again -> STILL shipping
    expect(w.getState()).toBe('shipping');
    expect(w.getErrors()).toEqual(['nope']);
  });
});

describe('confirmed is terminal', () => {
  it('accepts no further events of any kind', () => {
    const w = toReview();
    w.dispatch('SUBMIT');
    expect(w.getState()).toBe('confirmed');

    for (const event of ['NEXT', 'BACK', 'EDIT_SHIPPING', 'SUBMIT'] as const) {
      expect(() => w.dispatch(event), `${event} on confirmed`).toThrow(/Illegal transition/);
      expect(w.getState()).toBe('confirmed');
    }
  });
});

